func (d *Dispatcher) Record(event audit.Event) error {
	event.Kind = audit.NormalizeKind(event.Kind)
	return d.sink.Write(event)
}

func Classify(kind string) string {
	switch NormalizeKind(kind) {
	case "health", "probe":
		return "control"
	default:
		return "data"
	}
}

